import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

class KruskalMST {
    public static void main(String[] args) {
        Graph graph = new Graph.Builder()
            .vertices(4)
            .edge(0, 1, 10)
            .edge(1, 3, 15)
            .edge(2, 3, 4)
            .edge(2, 0, 6)
            .edge(0, 3, 5)
            .build();

        System.out.println("=== Min spanning tree ===");
        KruskalSolver minSolver = new KruskalSolver(RankedUnionFind::new, new AscendingWeight(), new LoggingObserver());
        List<Edge> mst = minSolver.solve(graph);

        System.out.println("\n=== Max spanning tree ===");
        KruskalSolver maxSolver = new KruskalSolver(RankedUnionFind::new, new DescendingWeight(), new LoggingObserver());
        maxSolver.solve(graph);
    }
}

class Graph {
    final int vertices;
    final List<Edge> edges;

    private Graph(Builder b) {
        this.vertices = b.vertices;
        this.edges = Collections.unmodifiableList(b.edges);
    }

    static class Builder {
        private int vertices;
        private final List<Edge> edges = new ArrayList<>();

        Builder vertices(int n) {
            this.vertices = n;
            return this;
        }

        Builder edge(int from, int to, int weight) {
            edges.add(new Edge(from, to, weight));
            return this;
        }

        Graph build() {
            return new Graph(this);
        }
    }
}

class KruskalSolver {
    private final UnionFindFactory ufFactory;
    private final EdgeSortingStrategy sortingStrategy;
    private final SolverObserver observer;

    KruskalSolver(UnionFindFactory ufFactory, EdgeSortingStrategy sortingStrategy) {
        this(ufFactory, sortingStrategy, new NoOpObserver());
    }

    KruskalSolver(UnionFindFactory ufFactory, EdgeSortingStrategy sortingStrategy, SolverObserver observer) {
        this.ufFactory = ufFactory;
        this.sortingStrategy = sortingStrategy;
        this.observer = observer;
    }

    List<Edge> solve(Graph graph) {
        Edge[] sorted = graph.edges.toArray(new Edge[0]);
        Arrays.sort(sorted, sortingStrategy.comparator());

        UnionFind uf = ufFactory.create(graph.vertices);
        List<Edge> mst = new ArrayList<>();

        for (Edge e : sorted) {
            observer.onEdgeConsidered(e);
            if (uf.find(e.from) != uf.find(e.to)) {
                uf.union(e.from, e.to);
                mst.add(e);
                observer.onEdgeAccepted(e, mst.size());
                if (mst.size() == graph.vertices - 1) break;
            } else {
                observer.onEdgeRejected(e);
            }
        }

        observer.onSolveComplete(mst, mst.stream().mapToInt(e -> e.weight).sum());
        return mst;
    }
}

